# -*- coding: utf-8 -*-
# GENERATED BY AI
"""KiCad symbol rendering.

Renders a symbol from a KiCad symbol library (``.kicad_sym`` file) as a
schematic-style SVG image, showing the body graphics, the pin leads, and
the pin numbers and names. Used by the connector ``symbol`` attribute; see
``docs/syntax.md``.

Parsing relies on the ``kiutils`` package (https://github.com/mvnmgrx/kiutils).
"""

import copy
import hashlib
import math
import tempfile
from pathlib import Path
from typing import Dict, List, Optional, Tuple

from kiutils.symbol import Symbol as KicadSymbol
from kiutils.symbol import SymbolLib

# Colors used when rendering the symbol (on a light background)
COLOR_BODY = "#333333"  # body graphics
COLOR_BACKGROUND = "#ffffff"  # body fills of type "background"
COLOR_PIN = "#333333"  # pin leads
COLOR_TEXT = "#333333"  # pin numbers and names

DEFAULT_LINE_WIDTH = 0.254  # mm, KiCad's default for symbol graphics
DEFAULT_FONT_SIZE = 1.27  # mm, KiCad's default for pin name/number text
DEFAULT_IMAGE_WIDTH = 200  # points, like WireViz image width attribute
MARGIN = 0.25  # mm between symbol bounding box and SVG border
PIN_NAME_OFFSET = 0.508  # mm, KiCad's default pin name offset
PIN_NUMBER_OFFSET = 0.8  # mm, distance between lead and pin number
PIN_LINE_WIDTH = 0.1524  # mm, KiCad's default pin lead width
INVERTED_PIN_RADIUS = 0.508  # mm, radius of an inverted pin's circle
NO_CONNECT_LENGTH = 0.508  # mm, half length of a no_connect pin's cross
TEXT_WIDTH_FACTOR = 0.7  # estimated glyph width per font size

# Keys allowed in the YAML symbol attribute
SYMBOL_ATTRIBUTE_KEYS = {"library", "part", "width", "height", "bgcolor", "caption"}


def _fmt(value: float) -> str:
    """Format a float without trailing zeros for use in SVG output."""
    if abs(value) < 5e-5:
        value = 0.0
    return f"{value:.4f}".rstrip("0").rstrip(".") or "0"


def _escape(text: str) -> str:
    """Escape a string for use in SVG text content."""
    return (
        str(text)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def _font_size(effects) -> float:
    """Return the font size defined by an effects token, in mm."""
    if effects is not None and effects.font is not None and effects.font.height:
        return float(effects.font.height)
    return DEFAULT_FONT_SIZE


def _item_width(item) -> float:
    """Return the stroke width of a symbol graphic item in mm."""
    stroke = getattr(item, "stroke", None)
    width = stroke.width if stroke is not None else None
    return float(width) if width else DEFAULT_LINE_WIDTH


def _dasharray(item) -> Optional[str]:
    """Map the KiCad stroke type of an item to an SVG stroke-dasharray."""
    stroke = getattr(item, "stroke", None)
    stroke_type = stroke.type if stroke is not None else None
    width = _item_width(item)
    if stroke_type == "dash":
        return f"{_fmt(3 * width)},{_fmt(2 * width)}"
    if stroke_type == "dot":
        return f"{_fmt(0.5 * width)},{_fmt(1.5 * width)}"
    if stroke_type == "dash_dot":
        return f"{_fmt(3 * width)},{_fmt(1.5 * width)},{_fmt(0.5 * width)},{_fmt(1.5 * width)}"
    if stroke_type == "dash_dot_dot":
        return (
            f"{_fmt(3 * width)},{_fmt(1.5 * width)},{_fmt(0.5 * width)},"
            f"{_fmt(1.5 * width)},{_fmt(0.5 * width)},{_fmt(1.5 * width)}"
        )
    return None  # solid, default, or unknown


class _Renderer:
    """Collects SVG fragments and the bounding box while walking the symbol.

    KiCad's coordinate system has its y axis pointing up, while SVG's y axis
    points down: all emitted coordinates have their y value negated. All
    units of a multi-unit symbol are drawn together, like in the symbol
    editor's "show all units" view.
    """

    def __init__(self, symbol: KicadSymbol):
        self.symbol = symbol
        self.min_x = math.inf
        self.min_y = math.inf
        self.max_x = -math.inf
        self.max_y = -math.inf
        self.graphics: List[str] = []
        self.pins: List[str] = []
        self.texts: List[str] = []

    # -- bounding box ------------------------------------------------------

    def _track(self, x: float, y: float) -> None:
        self.min_x = min(self.min_x, x)
        self.min_y = min(self.min_y, y)
        self.max_x = max(self.max_x, x)
        self.max_y = max(self.max_y, y)

    def _track_item(self, x: float, y: float, width: float) -> None:
        """Track a line/outline position including half the stroke width."""
        half = width / 2
        self._track(x - half, y - half)
        self._track(x + half, y + half)

    def _track_text(self, x: float, y: float, text: str, font_size: float) -> None:
        """Track the estimated extent of a text element."""
        half_width = TEXT_WIDTH_FACTOR * font_size * len(str(text)) / 2
        self._track(x - half_width, y - font_size)
        self._track(x + half_width, y + font_size)

    # -- graphics items ----------------------------------------------------

    def _fill(self, item) -> str:
        """Return the SVG fill color for a symbol graphic item."""
        fill = getattr(item, "fill", None)
        if fill is not None and fill.type == "outline":
            return COLOR_BODY
        if fill is not None and fill.type == "background":
            return COLOR_BACKGROUND
        return "none"

    def _stroke_attrs(self, item) -> str:
        """Return the SVG stroke attributes for a symbol graphic item."""
        dash = _dasharray(item)
        extra = f' stroke-dasharray="{dash}"' if dash else ""
        return f'stroke="{COLOR_BODY}" stroke-width="{_fmt(_item_width(item))}"{extra}'

    def _rect(self, item) -> str:
        start, end = item.start, item.end
        x1, y1 = float(start.X), -float(start.Y)
        x2, y2 = float(end.X), -float(end.Y)
        width = _item_width(item)
        for x, y in ((x1, y1), (x2, y2)):
            self._track_item(x, y, width)
        x, y = min(x1, x2), min(y1, y2)
        w, h = abs(x2 - x1), abs(y2 - y1)
        return (
            f'<rect x="{_fmt(x)}" y="{_fmt(y)}" width="{_fmt(w)}" '
            f'height="{_fmt(h)}" fill="{self._fill(item)}" '
            f'{self._stroke_attrs(item)}/>'
        )

    def _circle(self, item) -> str:
        center = item.center
        x, y = float(center.X), -float(center.Y)
        radius = float(item.radius)
        width = _item_width(item)
        for dx, dy in ((-radius, -radius), (radius, radius)):
            self._track_item(x + dx, y + dy, width)
        return (
            f'<circle cx="{_fmt(x)}" cy="{_fmt(y)}" r="{_fmt(radius)}" '
            f'fill="{self._fill(item)}" {self._stroke_attrs(item)}/>'
        )

    def _arc(self, item) -> str:
        start, mid, end = item.start, item.mid, item.end
        p0 = (float(start.X), -float(start.Y))
        pm = (float(mid.X), -float(mid.Y))
        p1 = (float(end.X), -float(end.Y))
        width = _item_width(item)
        for x, y in (p0, pm, p1):
            self._track_item(x, y, width)
        center = self._circumcenter(p0, pm, p1)
        if center is None:  # collinear points, fall back to a line
            return (
                f'<line x1="{_fmt(p0[0])}" y1="{_fmt(p0[1])}" '
                f'x2="{_fmt(p1[0])}" y2="{_fmt(p1[1])}" '
                f'{self._stroke_attrs(item)}/>'
            )
        radius = math.hypot(p0[0] - center[0], p0[1] - center[1])
        a0 = math.atan2(p0[1] - center[1], p0[0] - center[0])
        am = math.atan2(pm[1] - center[1], pm[0] - center[0])
        a1 = math.atan2(p1[1] - center[1], p1[0] - center[0])
        to_end = self._norm(a1 - a0)  # span when going in positive direction
        to_mid = self._norm(am - a0)
        if to_mid <= to_end:  # mid point is on the positive-direction arc
            sweep, span = 1, to_end
        else:
            sweep, span = 0, 2 * math.pi - to_end
        large = 1 if span > math.pi else 0
        return (
            f'<path d="M {_fmt(p0[0])} {_fmt(p0[1])} '
            f'A {_fmt(radius)} {_fmt(radius)} 0 {large} {sweep} '
            f'{_fmt(p1[0])} {_fmt(p1[1])}" fill="none" '
            f'{self._stroke_attrs(item)}/>'
        )

    @staticmethod
    def _norm(angle: float) -> float:
        while angle < 0:
            angle += 2 * math.pi
        while angle >= 2 * math.pi:
            angle -= 2 * math.pi
        return angle

    @staticmethod
    def _circumcenter(p0, p1, p2) -> Optional[Tuple[float, float]]:
        d = 2 * (p0[0] * (p1[1] - p2[1]) + p1[0] * (p2[1] - p0[1]) + p2[0] * (p0[1] - p1[1]))
        if abs(d) < 1e-12:
            return None
        a2 = p0[0] ** 2 + p0[1] ** 2
        b2 = p1[0] ** 2 + p1[1] ** 2
        c2 = p2[0] ** 2 + p2[1] ** 2
        ux = (a2 * (p1[1] - p2[1]) + b2 * (p2[1] - p0[1]) + c2 * (p0[1] - p1[1])) / d
        uy = (a2 * (p2[0] - p1[0]) + b2 * (p0[0] - p2[0]) + c2 * (p1[0] - p0[0])) / d
        return (ux, uy)

    def _polyline(self, item) -> str:
        width = _item_width(item)
        for point in item.points:
            self._track_item(float(point.X), -float(point.Y), width)
        points = " ".join(f"{_fmt(p.X)},{_fmt(-float(p.Y))}" for p in item.points)
        fill = self._fill(item)
        if fill != "none":  # a filled polyline is a closed polygon in KiCad
            return (
                f'<polygon points="{points}" fill="{fill}" '
                f'{self._stroke_attrs(item)}/>'
            )
        return (
            f'<polyline points="{points}" fill="none" '
            f'{self._stroke_attrs(item)}/>'
        )

    def _curve(self, item) -> str:
        # Approximated as a polyline; bezier curves are rare in symbols
        width = _item_width(item)
        for point in item.points:
            self._track_item(float(point.X), -float(point.Y), width)
        points = " ".join(f"{_fmt(p.X)},{_fmt(-float(p.Y))}" for p in item.points)
        return (
            f'<polyline points="{points}" fill="none" '
            f'{self._stroke_attrs(item)}/>'
        )

    def _text(self, item) -> None:
        if item.effects is not None and item.effects.hide:
            return
        self._draw_text(item.text, item.position, item.effects)

    def _text_box(self, item) -> None:
        size = getattr(item, "size", None)
        if size is not None and getattr(size, "X", None) is not None:
            x, y = float(item.position.X), -float(item.position.Y)
            w, h = float(size.X), float(size.Y)
            width = _item_width(item)
            self._track_item(x, y, width)
            self._track_item(x + w, y + h, width)
            self.graphics.append(
                f'<rect x="{_fmt(x)}" y="{_fmt(y)}" width="{_fmt(w)}" '
                f'height="{_fmt(h)}" fill="{self._fill(item)}" '
                f'{self._stroke_attrs(item)}/>'
            )
        if item.effects is None or not item.effects.hide:
            self._draw_text(item.text, item.position, item.effects)

    def _draw_text(self, text: str, position, effects) -> None:
        if not text:
            return
        font_size = _font_size(effects)
        x, y = float(position.X), -float(position.Y)
        angle = float(position.angle) if position.angle is not None else 0.0
        justify = effects.justify if effects is not None else None
        if justify is None or not justify.horizontally:
            anchor = "middle"
        elif justify.horizontally == "right":
            anchor = "end"
        else:
            anchor = "start"
        if justify is None or not justify.vertically:
            baseline = "central"
        elif justify.vertically == "top":
            baseline = "hanging"
        else:
            baseline = "auto"
        rotation = (
            f' transform="rotate({_fmt(angle)} {_fmt(x)} {_fmt(y)})"'
            if angle
            else ""
        )
        self._track_text(x, y, text, font_size)
        self.texts.append(
            f'<text x="{_fmt(x)}" y="{_fmt(y)}" '
            f'font-family="sans-serif" font-size="{_fmt(font_size)}" '
            f'fill="{COLOR_TEXT}" text-anchor="{anchor}" '
            f'dominant-baseline="{baseline}"{rotation}>'
            f"{_escape(text)}</text>"
        )

    # -- pins --------------------------------------------------------------

    def _pin(self, pin) -> None:
        if pin.hide:
            return
        position = pin.position
        x, y = float(position.X), -float(position.Y)
        angle = float(position.angle) if position.angle is not None else 0.0
        rad = math.radians(angle)
        length = float(pin.length)
        # The lead extends from the connection point towards the body
        tip_x = x + math.cos(rad) * length
        tip_y = y - math.sin(rad) * length
        self._track_item(x, y, PIN_LINE_WIDTH)
        self._track_item(tip_x, tip_y, PIN_LINE_WIDTH)
        self.pins.append(
            f'<line x1="{_fmt(x)}" y1="{_fmt(y)}" '
            f'x2="{_fmt(tip_x)}" y2="{_fmt(tip_y)}" '
            f'stroke="{COLOR_PIN}" stroke-width="{_fmt(PIN_LINE_WIDTH)}"/>'
        )
        self._pin_style(pin, x, y, rad)
        self._pin_number(pin, x, y, tip_x, tip_y, rad)
        self._pin_name(pin, tip_x, tip_y, rad, angle)

    def _pin_style(self, pin, x: float, y: float, rad: float) -> None:
        style = pin.graphicalStyle or "line"
        if style in ("inverted", "inverted_clock"):
            radius = INVERTED_PIN_RADIUS
            cx = x + math.cos(rad) * radius
            cy = y - math.sin(rad) * radius
            self._track_item(cx - radius, cy - radius, PIN_LINE_WIDTH)
            self._track_item(cx + radius, cy + radius, PIN_LINE_WIDTH)
            self.pins.append(
                f'<circle cx="{_fmt(cx)}" cy="{_fmt(cy)}" r="{_fmt(radius)}" '
                f'fill="{COLOR_BACKGROUND}" stroke="{COLOR_PIN}" '
                f'stroke-width="{_fmt(PIN_LINE_WIDTH)}"/>'
            )
        elif style in ("no_connect", "unconnected"):
            arm = NO_CONNECT_LENGTH
            for dx, dy in ((arm, arm), (arm, -arm)):
                x1, y1 = x - dx, y - dy
                x2, y2 = x + dx, y + dy
                self._track_item(x1, y1, PIN_LINE_WIDTH)
                self._track_item(x2, y2, PIN_LINE_WIDTH)
                self.pins.append(
                    f'<line x1="{_fmt(x1)}" y1="{_fmt(y1)}" '
                    f'x2="{_fmt(x2)}" y2="{_fmt(y2)}" '
                    f'stroke="{COLOR_PIN}" stroke-width="{_fmt(PIN_LINE_WIDTH)}"/>'
                )
        # other graphical styles are drawn as a plain lead

    def _pin_number(
        self, pin, x: float, y: float, tip_x: float, tip_y: float, rad: float
    ) -> None:
        if self.symbol.hidePinNumbers:
            return
        number = str(pin.number)
        if not number or number == "~":
            return
        font_size = _font_size(pin.numberEffects)
        # Draw the number beside the middle of the lead, perpendicular to it
        mid_x, mid_y = (x + tip_x) / 2, (y + tip_y) / 2
        nx = mid_x - math.sin(rad) * PIN_NUMBER_OFFSET
        ny = mid_y - math.cos(rad) * PIN_NUMBER_OFFSET
        self._track_text(nx, ny, number, font_size)
        self.texts.append(
            f'<text x="{_fmt(nx)}" y="{_fmt(ny)}" '
            f'font-family="sans-serif" font-size="{_fmt(font_size)}" '
            f'fill="{COLOR_TEXT}" text-anchor="middle" '
            f'dominant-baseline="central">{_escape(number)}</text>'
        )

    def _pin_name(self, pin, tip_x: float, tip_y: float, rad: float, angle: float) -> None:
        name = str(pin.name)
        if not name or name == "~" or self.symbol.pinNamesHide:
            return
        font_size = _font_size(pin.nameEffects)
        offset = float(self.symbol.pinNamesOffset or PIN_NAME_OFFSET)
        # Draw the name inside the body, just past the end of the lead
        nx = tip_x + math.cos(rad) * offset
        ny = tip_y - math.sin(rad) * offset
        anchor, baseline = self._name_anchor(angle)
        self._track_text(nx, ny, name, font_size)
        self.texts.append(
            f'<text x="{_fmt(nx)}" y="{_fmt(ny)}" '
            f'font-family="sans-serif" font-size="{_fmt(font_size)}" '
            f'fill="{COLOR_TEXT}" text-anchor="{anchor}" '
            f'dominant-baseline="{baseline}">{_escape(name)}</text>'
        )

    @staticmethod
    def _name_anchor(angle: float) -> Tuple[str, str]:
        """Return text anchor settings for a pin name by lead direction."""
        if angle == 90:  # lead points up, name sits above its end
            return "middle", "auto"
        if angle == 270:  # lead points down, name hangs below its end
            return "middle", "hanging"
        if angle == 180:  # lead points left, name extends to the left
            return "end", "central"
        return "start", "central"  # lead points right (default)

    # -- assembly ----------------------------------------------------------

    def run(self) -> Tuple[str, float, float]:
        graphics = list(self.symbol.graphicItems)
        pins = list(self.symbol.pins)
        for unit in self.symbol.units:
            graphics.extend(unit.graphicItems)
            pins.extend(unit.pins)

        for item in graphics:
            name = item.__class__.__name__
            if name == "SyRect":
                self.graphics.append(self._rect(item))
            elif name == "SyCircle":
                self.graphics.append(self._circle(item))
            elif name == "SyArc":
                self.graphics.append(self._arc(item))
            elif name == "SyPolyLine":
                self.graphics.append(self._polyline(item))
            elif name == "SyCurve":
                self.graphics.append(self._curve(item))
            elif name == "SyText":
                self._text(item)
            elif name == "SyTextBox":
                self._text_box(item)
            # other graphic item types are not rendered

        for pin in pins:
            self._pin(pin)

        if self.min_x is math.inf:  # symbol without graphics or pins
            self.min_x = self.min_y = -1.0
            self.max_x = self.max_y = 1.0

        min_x = self.min_x - MARGIN
        min_y = self.min_y - MARGIN
        width = self.max_x - self.min_x + 2 * MARGIN
        height = self.max_y - self.min_y + 2 * MARGIN

        svg = [
            # The XML declaration is required for Graphviz to recognize the
            # file as an SVG image (it detects the type by magic header).
            '<?xml version="1.0" encoding="UTF-8"?>',
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{_fmt(width)}mm" '
            f'height="{_fmt(height)}mm" viewBox="{_fmt(min_x)} {_fmt(min_y)} '
            f'{_fmt(width)} {_fmt(height)}">',
            *self.graphics,
            *self.pins,
            *self.texts,
            "</svg>",
        ]
        return "".join(svg), width, height


def _effective_symbol(
    symbol: KicadSymbol, library: Optional[SymbolLib] = None
) -> KicadSymbol:
    """Follow the ``extends`` chain to the symbol carrying the graphics.

    KiCad derived symbols inherit all graphics and pins from the symbol
    they extend, but keep their own pin number and pin name display
    settings, so those settings are carried over to the resolved symbol.
    """
    origin = symbol
    seen = set()
    while (
        symbol.extends
        and not symbol.graphicItems
        and not symbol.pins
        and not symbol.units
    ):
        if library is None or symbol.entryName in seen:
            break
        seen.add(symbol.entryName)
        parent_name = symbol.extends.split(":")[-1]
        parent = next(
            (s for s in library.symbols if s.entryName == parent_name), None
        )
        if parent is None:
            break
        symbol = parent
    if symbol is not origin:
        merged = copy.copy(symbol)
        merged.hidePinNumbers = origin.hidePinNumbers or symbol.hidePinNumbers
        merged.pinNamesHide = origin.pinNamesHide or symbol.pinNamesHide
        if origin.pinNamesOffset is not None:
            merged.pinNamesOffset = origin.pinNamesOffset
        symbol = merged
    return symbol


def render_symbol_svg(
    symbol: KicadSymbol, library: Optional[SymbolLib] = None
) -> Tuple[str, float, float]:
    """Render a KiCad symbol (parsed by kiutils) as an SVG image.

    Returns the SVG document as a string, plus its width and height in mm.
    """
    return _Renderer(_effective_symbol(symbol, library)).run()


def symbol_image(spec: Dict):
    """Create a WireViz Image by loading and rendering a KiCad symbol.

    ``spec`` is the value of the connector ``symbol`` attribute:
    a dict with a ``library`` (path to a ``.kicad_sym`` symbol library
    file) and a ``part`` (symbol name within the library), and optional
    ``width``, ``height``, ``bgcolor``, and ``caption`` for the resulting
    image.
    """
    from wireviz.DataClasses import Image  # imported here to avoid circular imports

    unknown = set(spec) - SYMBOL_ATTRIBUTE_KEYS
    if unknown:
        raise ValueError(
            f"Unknown symbol attribute(s): {', '.join(sorted(unknown))}"
        )

    library = spec.get("library")
    part = spec.get("part")
    if not library:
        raise ValueError("The symbol attribute requires a 'library'")
    library_path = Path(str(library))
    if library_path.suffix != ".kicad_sym":
        raise ValueError(
            "The symbol attribute 'library' must be a KiCad symbol "
            "library file (.kicad_sym)"
        )
    if not library_path.is_file():
        raise FileNotFoundError(f"KiCad symbol library not found: {library_path}")
    if not part:
        raise ValueError("The symbol attribute requires a 'part'")
    symbol_lib = SymbolLib.from_file(str(library_path))
    symbol = next(
        (s for s in symbol_lib.symbols if s.entryName == part), None
    )
    if symbol is None:
        raise ValueError(f"Symbol not found in library: {part}")

    svg, width_mm, height_mm = render_symbol_svg(symbol, symbol_lib)

    # Cache the rendered SVG, one file per unique rendering
    cache_dir = Path(tempfile.gettempdir()) / "wireviz-symbols"
    cache_dir.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256(svg.encode("utf-8")).hexdigest()[:8]
    svg_file = cache_dir / f"{library_path.stem}-{part}-{digest}.svg"
    if not svg_file.exists():
        svg_file.write_text(svg, encoding="utf-8")

    width = spec.get("width") or DEFAULT_IMAGE_WIDTH
    height = spec.get("height") or round(width * height_mm / width_mm)
    return Image(
        src=str(svg_file),
        width=int(width),
        height=int(height),
        bgcolor=spec.get("bgcolor"),
        caption=spec.get("caption"),
    )
